"""Set observed UI preconditions and verify newly rendered frames in diagnostic CI only."""
import json
from pathlib import Path

def replace_exact(source, old, new):
    if source.count(old) != 1:
        raise ValueError(f'expected exactly one {old[:100]}')
    return source.replace(old, new)

layout = Path('tests/wasm/persistence_layout.spec.js')
source = layout.read_text(encoding='utf-8')
for old, new in json.loads(r'''[["  const lateFailureLayout = makeInvalidSceneLayout(customizeLayout(canonicalLayout, 0.75, 1.5));","  const qrhiReady = () => consoleMessages.filter(message => message.includes('PJ_WASM_PLOT_RHI_READY backend=OpenGLES2/WebGL')).length;\n  const assertFreshFrame = async (stage, readyBefore, stateFrom) => {\n    await expect.poll(qrhiReady, { timeout: 10000 }).toBeGreaterThan(readyBefore);\n    const state = consoleMessages.slice(stateFrom).find(message => message.includes('PJ_WASM_PLOT_STATE count='));\n    const sequence = state?.match(/\\bsequence=(\\d+)\\b/)?.[1];\n    expect(sequence).toBeTruthy();\n    let end = -1;\n    await expect.poll(() => {\n      end = consoleMessages.findIndex((message, index) => index >= stateFrom &&\n        message.includes('PJ_WASM_PLOT_HOVER_PIXELS sequence=' + sequence + ' '));\n      return end;\n    }, { timeout: 10000 }).toBeGreaterThanOrEqual(stateFrom);\n    const start = Math.max(stateFrom, 1 + consoleMessages.slice(0, end).findLastIndex(\n      message => message.includes('PJ_WASM_PLOT_HOVER_PIXELS sequence='),\n    ));\n    const rows = consoleMessages.slice(start, end).filter(message => message.includes('PJ_WASM_PLOT_CURVE_PIXELS'));\n    expect(rows).toHaveLength(1);\n    const curve = rows[0].match(/layout-open\\/temp:#[0-9a-fA-F]+:(\\d+)/);\n    expect(Number(curve?.[1] || 0)).toBeGreaterThan(0);\n    expect(errors).toEqual([]);\n    console.log('QRHI_RESTORE_FRAME', stage, sequence, Number(curve[1]));\n  };\n  const readyBeforeLate = qrhiReady();\n  const lateFailureLayout = makeInvalidSceneLayout(customizeLayout(canonicalLayout, 0.75, 1.5));"],["  const afterLateFailure = await requestPlotState(page, consoleMessages, stateMessages);\n  stateMessages += 1;","  const rollbackStateFrom = consoleMessages.length;\n  const afterLateFailure = await requestPlotState(page, consoleMessages, stateMessages);\n  stateMessages += 1;\n  await assertFreshFrame('rollback', readyBeforeLate, rollbackStateFrom);"],["  const validChooser = await openLayoutChooser(page);\n  await validChooser.setFiles({\n    name: 'workspace-one.pj4.xml',","  const readyBeforeValid = qrhiReady();\n  const validChooser = await openLayoutChooser(page);\n  await validChooser.setFiles({\n    name: 'workspace-one.pj4.xml',"],["  const restored = await requestPlotState(page, consoleMessages, stateMessages);\n  stateMessages += 1;\n  expect(restored.count).toBe(1);\n  expect(restored.titles).toEqual(['layout-open/temp']);","  const validStateFrom = consoleMessages.length;\n  const restored = await requestPlotState(page, consoleMessages, stateMessages);\n  stateMessages += 1;\n  await assertFreshFrame('first-valid', readyBeforeValid, validStateFrom);\n  expect(restored.count).toBe(1);\n  expect(restored.titles).toEqual(['layout-open/temp']);"],["  const secondValidChooser = await openLayoutChooser(page);\n  await secondValidChooser.setFiles({\n    name: 'workspace-two.pj4.xml',","  const readyBeforeSecondValid = qrhiReady();\n  const secondValidChooser = await openLayoutChooser(page);\n  await secondValidChooser.setFiles({\n    name: 'workspace-two.pj4.xml',"],["  const reopened = await requestPlotState(page, consoleMessages, stateMessages);\n  stateMessages += 1;","  const reopenStateFrom = consoleMessages.length;\n  const reopened = await requestPlotState(page, consoleMessages, stateMessages);\n  stateMessages += 1;\n  await assertFreshFrame('second-valid', readyBeforeSecondValid, reopenStateFrom);"]]'''):
    source = replace_exact(source, old, new)
layout.write_text(source, encoding='utf-8')

plot = Path('tests/wasm/plotting.spec.js')
source = plot.read_text(encoding='utf-8')
for name, edits in json.loads(r'''[["Shift-drag seeks",[["  const initial = await requestPlotState(page, consoleMessages, stateMessages);","  const defaultState = await requestPlotState(page, consoleMessages, stateMessages++);\n  expect(defaultState.trackerEnabled).toBe(true);\n  expect(defaultState.trackerParameter).toBe(1);\n  // A cached atlas emits no new TEXT_OK line when the layout is unchanged, so start before the UI transition.\n  textMessages = countMessages(consoleMessages, 'PJ_WASM_PLOT_TEXT_OK');\n  textPixelMessages = countMessages(consoleMessages, 'PJ_WASM_PLOT_TEXT_PIXELS');\n  const lineOnlyFrom = consoleMessages.length;\n  await page.evaluate(() => {\n    window.pjWasmCycleTimeTrackerProbe();\n    window.pjWasmCycleTimeTrackerProbe();\n  });\n  await expect.poll(() => consoleMessages.slice(lineOnlyFrom).some(message =>\n    /PJ_WASM_PLOT_TEXT_OK legend_layers=1 marker_labels=0 .* vertices=6 /.test(message),\n  ), { timeout: 10000 }).toBe(true);\n  const initial = await requestPlotState(page, consoleMessages, stateMessages);"],["  expect(initial.trackerParameter).toBe(1);","  expect(initial.trackerParameter).toBe(0);"],["  // Before the first seek the tracker's logical label is outside the imported\n  // range, so only the legend produces visible raster pixels.","  // Explicit line-only baseline keeps the legend but suppresses value labels."],["  await seekQtPlot(page, canvas, 0.25, 0.70);","  // The state qInfo is synchronous, while its framebuffer is read 250 ms later.\n  // The tracker log has no sequence, but the hover log ending that readback does.\n  const trackerForState = async (from) => {\n    const stateLog = consoleMessages.slice(from).find(message => message.includes('PJ_WASM_PLOT_STATE count='));\n    const sequence = stateLog?.match(/\\bsequence=(\\d+)\\b/)?.[1];\n    expect(sequence).toBeTruthy();\n    const frameMarker = `PJ_WASM_PLOT_HOVER_PIXELS sequence=${sequence} `;\n    let end = -1;\n    await expect.poll(() => {\n      end = consoleMessages.findIndex((message, index) => index >= from && message.includes(frameMarker));\n      return end;\n    }, { timeout: 10000 }).toBeGreaterThanOrEqual(from);\n    const start = Math.max(from, 1 + consoleMessages.slice(0, end).findLastIndex(\n      message => message.includes('PJ_WASM_PLOT_HOVER_PIXELS sequence='),\n    ));\n    const trackerLogs = consoleMessages.slice(start, end).filter(message => message.includes('PJ_WASM_PLOT_TRACKER'));\n    expect(trackerLogs).toHaveLength(1);\n    return requestTrackerReadback(trackerLogs, 0);\n  };\n  await page.evaluate(() => window.pjWasmCycleTimeTrackerProbe());\n  const restoreFrom = consoleMessages.length;\n  expect((await requestPlotState(page, consoleMessages, stateMessages++)).trackerParameter).toBe(1);\n  await trackerForState(restoreFrom);\n  await seekQtPlot(page, canvas, 0.25, 0.70);"],["  const forward = await requestPlotState(page, consoleMessages, stateMessages);\n  stateMessages += 1;\n  const forwardTracker = await requestTrackerReadback(consoleMessages, trackerMessages);\n  trackerMessages += 1;","  const forwardFrom = consoleMessages.length;\n  const forward = await requestPlotState(page, consoleMessages, stateMessages);\n  stateMessages += 1;\n  const forwardTracker = await trackerForState(forwardFrom);\n  console.log('SHIFT_FORWARD', JSON.stringify({time:forward.time, view:forward.view, pixels:forwardTracker}));"],["  const backward = await requestPlotState(page, consoleMessages, stateMessages);\n  stateMessages += 1;\n  const backwardTracker = await requestTrackerReadback(consoleMessages, trackerMessages);","  const backwardFrom = consoleMessages.length;\n  const backward = await requestPlotState(page, consoleMessages, stateMessages);\n  stateMessages += 1;\n  const backwardTracker = await trackerForState(backwardFrom);\n  console.log('SHIFT_BACKWARD', JSON.stringify({time:backward.time, view:backward.view, pixels:backwardTracker}));"]]],["rasterizes legend and tracker text",[["    const state = await requestPlotState(page, consoleMessages, stateMessages);\n    stateMessages += 1;\n    await requestPlotText(consoleMessages, textMessages);","    const defaultState = await requestPlotState(page, consoleMessages, stateMessages++);\n    expect(defaultState.trackerEnabled).toBe(true);\n    expect(defaultState.trackerParameter).toBe(1);\n    // Record before changing modes; the identical-atlas fast path emits no second TEXT_OK.\n    textMessages = countMessages(consoleMessages, 'PJ_WASM_PLOT_TEXT_OK');\n    textPixelMessages = countMessages(consoleMessages, 'PJ_WASM_PLOT_TEXT_PIXELS');\n    const lineOnlyFrom = consoleMessages.length;\n    await page.evaluate(() => {\n      window.pjWasmCycleTimeTrackerProbe();\n      window.pjWasmCycleTimeTrackerProbe();\n    });\n    await expect.poll(() => consoleMessages.slice(lineOnlyFrom).some(message =>\n      /PJ_WASM_PLOT_TEXT_OK legend_layers=1 marker_labels=0 .* vertices=6 /.test(message),\n    ), { timeout: 10000 }).toBe(true);\n    const state = await requestPlotState(page, consoleMessages, stateMessages++);\n    expect(state.trackerParameter).toBe(0);\n    const initialText = await requestPlotText(consoleMessages, textMessages);\n    expect(initialText.legendLayers).toBe(1);\n    expect(initialText.markerLabels).toBe(0);"],["    await seekQtPlot(page, canvas, 0.25, 0.55);","    await page.evaluate(() => window.pjWasmCycleTimeTrackerProbe());\n    expect((await requestPlotState(page, consoleMessages, stateMessages++)).trackerParameter).toBe(1);\n    await requestPlotTextPixels(consoleMessages, textPixelMessages);\n    textMessages = countMessages(consoleMessages, 'PJ_WASM_PLOT_TEXT_OK');\n    textPixelMessages = countMessages(consoleMessages, 'PJ_WASM_PLOT_TEXT_PIXELS');\n    await seekQtPlot(page, canvas, 0.25, 0.55);"]]],["two split QRhi plots",[["  expect(populated.plots.every(plot => plot.readback.textPixels === 0)).toBe(true);","  const readMode = () => requestPlotState(page, consoleMessages, countMessages(consoleMessages, 'PJ_WASM_PLOT_STATE count='));\n  const defaultState = await readMode();\n  expect(defaultState.trackerEnabled).toBe(true);\n  expect(defaultState.trackerParameter).toBe(1);\n  await page.evaluate(() => {\n    window.pjWasmCycleTimeTrackerProbe();\n    window.pjWasmCycleTimeTrackerProbe();\n  });\n  expect((await readMode()).trackerParameter).toBe(0);\n  const noLegends = await requestMultiPlotState(page, consoleMessages, multiMessages++);\n  expect(noLegends.plots.map(plot => plot.plotId)).toEqual(populated.plots.map(plot => plot.plotId));\n  expect(noLegends.plots.every(plot => plot.readback.textPixels === 0)).toBe(true);"],["  const initialViews = new Map(populated.plots.map(plot => [plot.plotId, plot.view]));","  await page.evaluate(() => window.pjWasmCycleTimeTrackerProbe());\n  expect((await readMode()).trackerParameter).toBe(1);\n  const initialViews = new Map(populated.plots.map(plot => [plot.plotId, plot.view]));"]]]]'''):
    prefix = "test('" + name
    if source.count(prefix) != 1:
        raise ValueError(f'expected exactly one {prefix}')
    a = source.index(prefix)
    b = source.find('\ntest(', a + 1)
    if b < 0:
        b = len(source)
    block = source[a:b]
    for old, new in edits:
        block = replace_exact(block, old, new)
    source = source[:a] + block + source[b:]
plot.write_text(source, encoding='utf-8')
